/// The built-in fallback font: PT Mono (Paratype, SIL Open Font License),
/// used by `Text` whenever no font is set on the context or the named font
/// is not loaded. The glyph metrics are embedded as BMFont data so
/// measurement works in Foundation-free cross-platform code; the atlas page
/// is embedded as a base64 png (losslessly recompressed) that each
/// platform's resource manager registers under `font.pageTextureName` at
/// startup, so default-font text renders with no game-side setup.
public enum DefaultHUDFont {
    public static let font: BitmapFont = {
        guard let font = try? BitmapFont(fromString: fntData) else {
            fatalError("embedded default HUD font data failed to parse")
        }
        return font
    }()

